533	async function loadStore(file: string): Promise<Store> {
534	  let text: string;
535	  try {
536	    text = await readFile(file, 'utf8');
537	  } catch (err) {
538	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore();
539	    throw new BizError(`无法读取数据文件 ${file}: ${(err as Error).message}`);
540	  }
541	  let raw: unknown;
542	  try {
543	    raw = JSON.parse(text);
544	  } catch (err) {
545	    throw new BizError(
546	      `数据文件 ${file} 已损坏，不是合法 JSON：${(err as Error).message}（原文件已保留，未当作空数据覆盖）`,
547	    );
548	  }
549	  return validateStore(raw, file);
