552	// 先完整写入临时文件，再原子改名；任何失败都不触碰原文件
553	async function saveStore(file: string, store: Store): Promise<void> {
554	  let json: string;
555	  try {
556	    json = JSON.stringify(store, null, 2) + '\n';
557	  } catch (err) {
558	    throw new BizError(`序列化数据失败：${(err as Error).message}（原文件已保留）`);
559	  }
560	  const tmp = `${file}.${process.pid}.tmp`;
561	  try {
562	    await writeFile(tmp, json, {encoding: 'utf8', flag: 'wx'});
563	    await rename(tmp, file);
564	  } catch (err) {
565	    await unlink(tmp).catch(() => {});
566	    throw new BizError(`保存数据文件 ${file} 失败：${(err as Error).message}（原文件已保留）`);
567	  }
