574	function formatResourceIds(store: Store, ids: string[]): string {
575	  return ids
576	    .map((id) => {
577	      const r = store.resources.find((x) => x.id === id);
578	      return r ? `${id}（${r.name}）` : id;
579	    })
580	    .join('、');
581	}
