603	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
604	  return mergeIntervals(
605	    r.open.map(
606	      ([s, e]) =>
607	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
608	    ),
609	  );
610	}
611	
612	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
613	function subtractSegments(
614	  segments: Array<[number, number]>,
615	  cuts: Array<[number, number]>,
616	): Array<[number, number]> {
617	  let result = segments;
618	  for (const [cs, ce] of mergeIntervals(cuts)) {
619	    const next: Array<[number, number]> = [];
620	    for (const [s, e] of result) {
621	      if (ce <= s || e <= cs) {
622	        next.push([s, e]);
623	        continue;
624	      }
625	      if (s < cs) next.push([s, cs]);
626	      if (ce < e) next.push([ce, e]);
627	    }
628	    result = next;
629	  }
630	  return result;
631	}
