633	// 某资源的有效停用记录（按开始时间、标识排序）
634	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
635	  return store.closures
636	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
637	    .sort(
638	      (a, b) =>
639	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
640	        a.id.localeCompare(b.id),
641	    );
642	}
643	
644	// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）
645	function availableSegmentsOf(store: Store, r: ResourceRec): Array<[number, number]> {
646	  const cuts = activeClosuresOf(store, r.id).map(
647	    (c) =>
648	      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
649	  );
650	  return subtractSegments(openSegmentsOf(r), cuts);
651	}
