692	// 校验每个资源的实际可用时间都能完整覆盖 [startMin, endMin)
693	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
694	  const failing = findCoverageGaps(store, ids, startMin, endMin);
695	  if (failing.length > 0) {
696	    throw new BizError(
697	      '开放时间不足，以下资源的实际可用时间（开放区间扣除有效停用）不能完整覆盖预约区间：\n' +
698	        gapLines(failing, '').join('\n'),
699	    );
700	  }
701	}
