708	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
709	function findConflicts(
710	  store: Store,
711	  ids: string[],
712	  startMin: number,
713	  endMin: number,
714	  excludeBookingId?: string,
715	): Conflict[] {
716	  const wanted = new Set(ids);
717	  const conflicts: Conflict[] = [];
718	  for (const b of store.bookings) {
719	    if (b.status !== 'active') continue;
720	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
721	    const bStart = parseDateTime(b.start, '预约开始时间');
722	    const bEnd = parseDateTime(b.end, '预约结束时间');
723	    const overlap = bStart < endMin && startMin < bEnd;
724	    if (!overlap) continue;
725	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
726	    if (shared.length > 0) conflicts.push({booking: b, shared});
727	  }
728	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
729	  return conflicts;
730	}
731	
732	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
733	  if (conflicts.length === 0) return;
734	  const lines = conflicts.map(
735	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
736	  );
737	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
738	}
