1060	async function cmdRescheduleBatch(args: string[]): Promise<void> {
1061	  const {values, positionals} = parseFlags(args, []);
1062	  if (values.size > 0) {
1063	    throw new UsageError(
1064	      `reschedule-batch 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
1065	    );
1066	  }
1067	  if (positionals.length !== 1) {
1068	    throw new UsageError('用法: reschedule-batch <改期清单文件>');
1069	  }
1070	  const manifestFile = positionals[0];
1071	
1072	  const file = activeDataFile;
1073	  const store = await loadStore(file);
1074	  const records = parseManifestShape(await loadManifest(manifestFile), manifestFile);
1075	
1076	  // 第一阶段：逐项做与业务数据相关的基础校验，收集全部问题后一次性拒绝整批
1077	  const problems: string[] = [];
1078	  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
1079	  const planned: Array<BatchTarget | null> = [];
1080	  records.forEach((rec, idx) => {
1081	    const at = `第 ${idx + 1} 项（${rec.bookingId as string}）`;
1082	    let ok = true;
1083	
1084	    const firstAt = seenBooking.get(rec.bookingId as string);
1085	    if (firstAt !== undefined) {
1086	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
1087	      ok = false;
1088	    } else {
1089	      seenBooking.set(rec.bookingId as string, idx + 1);
1090	    }
1091	
1092	    const booking = store.bookings.find((b) => b.id === rec.bookingId);
1093	    if (!booking) {
1094	      problems.push(`${at} 未知预约标识: ${rec.bookingId}`);
1095	      ok = false;
1096	    } else if (booking.status === 'cancelled') {
1097	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
1098	      ok = false;
1099	    }
1100	
1101	    const rawRids = rec.resourceIds as string[];
1102	    const dupes = rawRids.filter((id, j) => rawRids.indexOf(id) !== j);
1103	    if (dupes.length > 0) problems.push(`${at} 资源重复指定: ${[...new Set(dupes)].join('、')}`);
1104	    const unknown = [...new Set(rawRids)]
1105	      .filter((id) => !store.resources.some((r) => r.id === id))
1106	      .sort();
1107	    if (unknown.length > 0) problems.push(`${at} 未知资源标识: ${unknown.join('、')}`);
1108	
1109	    let startMin = 0;
1110	    let endMin = 0;
1111	    let startParsed = false;
1112	    let endParsed = false;
1113	    try {
1114	      startMin = parseDateTime(rec.start as string, `${at} 目标开始时间`);
1115	      startParsed = true;
1116	    } catch (err) {
1117	      problems.push((err as BizError).message);
1118	    }
1119	    try {
1120	      endMin = parseDateTime(rec.end as string, `${at} 目标结束时间`);
1121	      endParsed = true;
1122	    } catch (err) {
1123	      problems.push((err as BizError).message);
1124	    }
1125	    if (startParsed && endParsed && endMin <= startMin) {
1126	      problems.push(
1127	        `${at} 目标结束时间必须晚于开始时间（开始: ${rec.start}，结束: ${rec.end}），允许跨日`,
1128	      );
1129	      ok = false;
1130	    }
1131	
1132	    if (!ok || !booking) {
1133	      planned.push(null);
1134	      return;
1135	    }
1136	    planned.push({
1137	      index: idx,
1138	      booking,
1139	      startRaw: rec.start as string,
1140	      endRaw: rec.end as string,
1141	      startMin,
1142	      endMin,
1143	      resourceIds: [...new Set(rawRids)].sort(),
1144	    });
1145	  });
1146	
1147	  if (problems.length > 0) {
1148	    throw new BizError(`改期清单 ${manifestFile} 校验失败，整批拒绝（原有安排保持不变）：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1149	  }
1150	  const targets = planned as BatchTarget[];
1151	  const batchIds = new Set(targets.map((t) => t.booking.id));
1152	
1153	  // 第二阶段：对“整批完成后”的安排做校验。
1154	  // 本批预约的旧占用一律不视为障碍（findConflicts 排除本批全部标识）；
1155	  // 障碍只来自本批之外的有效预约，以及本批各项的目标安排彼此之间。
1156	  const failures: BatchFailure[] = [];
1157	  for (const t of targets) {
1158	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
1159	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
1160	      (c) => !batchIds.has(c.booking.id),
1161	    );
1162	    const wanted = new Set(t.resourceIds);
1163	    const internal: BatchFailure['internal'] = [];
1164	    for (const o of targets) {
1165	      if (o.index === t.index) continue;
1166	      const overlap = o.startMin < t.endMin && t.startMin < o.endMin;
1167	      if (!overlap) continue;
1168	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
1169	      if (shared.length > 0) internal.push({other: o, shared});
1170	    }
1171	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1172	      failures.push({target: t, gaps, external, internal});
1173	    }
1174	  }
1175	
1176	  if (failures.length > 0) {
1177	    // 按清单顺序报告全部不满足条件的项；批内冲突在双方项中都会出现
1178	    const blocks = failures.map(({target: t, gaps, external, internal}) => {
1179	      const lines = [`第 ${t.index + 1} 项 ${t.booking.id} 目标 ${t.startRaw} → ${t.endRaw}：`];
1180	      if (gaps.length > 0) {
1181	        lines.push('  开放不足资源:');
1182	        lines.push(...gapLines(gaps, '    '));
1183	      }
1184	      if (external.length + internal.length > 0) {
1185	        lines.push('  冲突预约:');
1186	        for (const c of external) {
1187	          lines.push(
1188	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
1189	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
1190	          );
1191	        }
1192	        for (const x of internal) {
1193	          lines.push(
1194	            `    - ${x.other.booking.id}（本批第 ${x.other.index + 1} 项目标 ${x.other.startRaw} → ${x.other.endRaw}）` +
1195	              `：共同资源 ${formatResourceIds(store, x.shared)}`,
1196	          );
1197	        }
1198	      }
1199	      return lines.join('\n');
1200	    });
1201	    throw new BizError(
1202	      `批量改期失败：共 ${failures.length} 项不满足条件（按清单顺序），整批未改动：\n${blocks.join('\n')}`,
1203	    );
1204	  }
1205	
1206	  // 全部验证通过：一次性替换各项目标安排并原子落盘。
1207	  // 仅改时间与资源；标识、status、seriesId、标识计数全部不变，不创建任何预约或系列。
1208	  // 若保存失败，磁盘原文件保留；本进程亦以退出码 1 结束，不会报告成功。
1209	  const noChange = targets.every(
1210	    (t) =>
1211	      t.booking.start === t.startRaw &&
1212	      t.booking.end === t.endRaw &&
1213	      t.booking.resourceIds.length === t.resourceIds.length &&
1214	      t.booking.resourceIds.every((id, j) => id === t.resourceIds[j]),
1215	  );
1216	  if (noChange) {
1217	    // 幂等：提交的安排与现状完全一致时成功且不触碰数据文件
1218	    console.log(
1219	      `批量改期成功：共 ${targets.length} 项，安排均与现状一致，无业务变化（标识与系列归属不变，数据文件未改动）`,
1220	    );
1221	    for (const t of targets) {
1222	      console.log(`第 ${t.index + 1} 项 ${t.booking.id}: ${t.startRaw} → ${t.endRaw}`);
1223	    }
1224	    return;
1225	  }
1226	  for (const t of targets) {
1227	    t.booking.start = t.startRaw;
1228	    t.booking.end = t.endRaw;
1229	    t.booking.resourceIds = t.resourceIds;
1230	  }
1231	  await saveStore(file, store);
1232	
1233	  console.log(`批量改期成功：共 ${targets.length} 项（标识与系列归属不变，未创建预约或系列，未推进标识计数）`);
1234	  for (const t of targets) {
1235	    console.log(`第 ${t.index + 1} 项 ${t.booking.id}:`);
1236	    if (t.booking.seriesId) console.log(`  所属系列: ${t.booking.seriesId}（保持不变）`);
1237	    console.log(`  时间: ${t.startRaw} → ${t.endRaw}`);
1238	    console.log(`  资源: ${formatResourceIds(store, t.resourceIds)}`);
1239	  }
1240	}
