1296	// 解析正整数次数（不接受 0、负数、小数与前导零）
1297	function parseOccurrences(raw: string): number {
1298	  if (!/^[1-9]\d*$/.test(raw)) {
1299	    throw new BizError(`次数非法: “${raw}”，必须是正整数（含首项）`);
1300	  }
1301	  const n = Number(raw);
1302	  if (n > MAX_OCCURRENCES) {
1303	    throw new BizError(`次数过大: “${raw}”，最大为 ${MAX_OCCURRENCES}`);
1304	  }
