1315	// 按周展开系列：每项相对前一项将起止时间同时后移 7 个营业地日历日，
1316	// 时刻与跨日长度保持不变。任何一项超出四位年份范围即整体拒绝。
1317	function planWeeklyMembers(startMin: number, endMin: number, count: number): PlannedMember[] {
1318	  const members: PlannedMember[] = [];
1319	  for (let i = 0; i < count; i++) {
1320	    const s = startMin + i * 7 * 1440;
1321	    const e = endMin + i * 7 * 1440;
1322	    const startRaw = formatDateTime(s);
1323	    const endRaw = formatDateTime(e);
1324	    if (startRaw === null || endRaw === null) {
1325	      const nth = i + 1;
1326	      throw new BizError(
1327	        `系列第 ${nth} 项（约第 ${nth} 周）的时间超出四位年份范围（${MIN_YEAR}-${MAX_YEAR}），无法创建：` +
1328	          '请缩短次数或改选更早的首项时间',
1329	      );
1330	    }
1331	    members.push({startRaw, endRaw, startMin: s, endMin: e});
1332	  }
1333	  return members;
1334	}
