1337	interface MemberFailure {
1338	  index: number; // 0 基
1339	  startRaw: string;
1340	  endRaw: string;
1341	  gaps: CoverageGap[];
1342	  conflicts: Conflict[]; // 与既有有效预约的冲突
1343	  internal: Array<{other: PlannedMember; otherIndex: number}>; // 与系列内其他成员的冲突
1344	}
