1617	async function cmdProcessWaitlist(args: string[]): Promise<void> {
1618	  const {values, positionals} = parseFlags(args, []);
1619	  if (values.size > 0) {
1620	    throw new UsageError(`process-waitlist 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
1621	  }
1622	  if (positionals.length > 0) {
1623	    throw new UsageError(`process-waitlist 不接受位置参数: ${positionals.join(' ')}`);
1624	  }
1625	
1626	  const file = activeDataFile;
1627	  const store = await loadStore(file);
1628	
1629	  // 已兑现/已取消项永不重新处理；只按登记顺序遍历等待项
1630	  const waiting = store.waitlist.filter((w) => w.status === 'waiting');
1631	  if (waiting.length === 0) {
1632	    // 明确说明且不改变记录或计数（不落盘）
1633	    if (store.waitlist.length === 0) {
1634	      console.log('候补队列为空，没有可处理的候补；记录与标识计数不变。');
1635	    } else {
1636	      console.log('候补队列中没有等待中的候补（均已兑现或已取消）；记录与标识计数不变。');
1637	    }
1638	    return;
1639	  }
1640	
1641	  // 本轮已选中项（即时预约标识在选中时分配，全部成功后一次性落盘；
1642	  // 若保存失败，磁盘原文件、记录与计数均不变）
1643	  const selected: Array<{w: WaitlistRec; bookingId: string; startMin: number; endMin: number}> = [];
1644	  const blocked: Array<{
1645	    w: WaitlistRec;
1646	    gaps: CoverageGap[];
1647	    conflicts: PendingConflict[];
1648	  }> = [];
1649	
1650	  for (const w of waiting) {
1651	    const startMin = parseDateTime(w.start, '候补开始时间');
1652	    const endMin = parseDateTime(w.end, '候补结束时间');
1653	
1654	    // 1) 重查开放覆盖（资源开放区间可能已变化）
1655	    const gaps = findCoverageGaps(store, w.resourceIds, startMin, endMin);
1656	
1657	    // 2) 与当前全部有效预约（含系列成员，已取消不占用）求冲突
1658	    const wanted = new Set(w.resourceIds);
1659	    const conflicts: PendingConflict[] = [];
1660	    for (const b of store.bookings) {
1661	      if (b.status !== 'active') continue;
1662	      const bStart = parseDateTime(b.start, '预约开始时间');
1663	      const bEnd = parseDateTime(b.end, '预约结束时间');
1664	      if (!(bStart < endMin && startMin < bEnd)) continue;
1665	      const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1666	      if (shared.length > 0) conflicts.push({bookingId: b.id, start: b.start, end: b.end, shared});
1667	    }
1668	    // 3) 与本轮已选中项求冲突——后来者不能顶掉先选中者，顺序绝不改变
1669	    for (const s of selected) {
1670	      if (!(s.startMin < endMin && startMin < s.endMin)) continue;
1671	      const shared = s.w.resourceIds.filter((id) => wanted.has(id)).sort();
1672	      if (shared.length > 0) {
1673	        conflicts.push({
1674	          bookingId: s.bookingId,
1675	          start: s.w.start,
1676	          end: s.w.end,
1677	          shared,
1678	          fromWaitlistId: s.w.id,
1679	        });
1680	      }
1681	    }
1682	    conflicts.sort((a, b) => a.bookingId.localeCompare(b.bookingId));
1683	
1684	    if (gaps.length === 0 && conflicts.length === 0) {
1685	      // 全部资源可用才选中；受阻项跳过并继续检查后项
1686	      store.bookingSeq += 1;
1687	      const bookingId = `B${String(store.bookingSeq).padStart(4, '0')}`;
1688	      selected.push({w, bookingId, startMin, endMin});
1689	    } else {
1690	      blocked.push({w, gaps, conflicts});
1691	    }
1692	  }
1693	
1694	  if (selected.length === 0) {
1695	    // 没有可兑现项也成功：明确说明，不保存、不改变记录或计数
1696	    console.log(
1697	      `候补处理完成：本轮处理 ${waiting.length} 项等待候补，没有可兑现项（开放不足或仍有冲突），` +
1698	        '全部继续等待；记录、占用与标识计数不变。',
1699	    );
1700	    for (const {w, gaps, conflicts} of blocked) {
1701	      console.log(renderBlocked(store, w, gaps, conflicts));
1702	    }
1703	    return;
