if (kind === 'flexible') {
  if (durationMinutes === undefined) {
    bad(`${at}(${w.id}) 弹性候补缺少 durationMinutes`);
  } else if (durationMinutes > we - ws) {
    bad(`${at}(${w.id}) 所需时长 ${durationMinutes} 分钟超过窗口长度 ${we - ws} 分钟`);
