1726	  // 若保存失败，磁盘原文件、记录与计数均不变）
1727	  const selected: Array<{w: WaitlistRec; bookingId: string; startMin: number; endMin: number}> = [];
1728	  const blocked: Array<{
1729	    w: WaitlistRec;
1730	    gaps: CoverageGap[];
1731	    conflicts: PendingConflict[];
1732	  }> = [];
1733	
1734	  for (const w of waiting) {
