1736	    const endMin = parseDateTime(w.end, '候补结束时间');
1737	
1738	    // 1) 重查开放覆盖（资源开放区间可能已变化）
1739	    const gaps = findCoverageGaps(store, w.resourceIds, startMin, endMin);
1740	
1741	    // 2) 与当前全部有效预约（含系列成员，已取消不占用）求冲突
1742	    const wanted = new Set(w.resourceIds);
1743	    const conflicts: PendingConflict[] = [];
1744	    for (const b of store.bookings) {
1745	      if (b.status !== 'active') continue;
1746	      const bStart = parseDateTime(b.start, '预约开始时间');
1747	      const bEnd = parseDateTime(b.end, '预约结束时间');
1748	      if (!(bStart < endMin && startMin < bEnd)) continue;
1749	      const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1750	      if (shared.length > 0) conflicts.push({bookingId: b.id, start: b.start, end: b.end, shared});
1751	    }
1752	    // 3) 与本轮已选中项求冲突——后来者不能顶掉先选中者，顺序绝不改变
1753	    for (const s of selected) {
1754	      if (!(s.startMin < endMin && startMin < s.endMin)) continue;
1755	      const shared = s.w.resourceIds.filter((id) => wanted.has(id)).sort();
1756	      if (shared.length > 0) {
1757	        conflicts.push({
1758	          bookingId: s.bookingId,
1759	          start: s.w.start,
1760	          end: s.w.end,
1761	          shared,
1762	          fromWaitlistId: s.w.id,
1763	        });
1764	      }
1765	    }
1766	    conflicts.sort((a, b) => a.bookingId.localeCompare(b.bookingId));
1767	
1768	    if (gaps.length === 0 && conflicts.length === 0) {
1769	      // 全部资源可用才选中；受阻项跳过并继续检查后项
1770	      store.bookingSeq += 1;
1771	      const bookingId = `B${String(store.bookingSeq).padStart(4, '0')}`;
1772	      selected.push({w, bookingId, startMin, endMin});
1773	    } else {
1774	      blocked.push({w, gaps, conflicts});
1775	    }
1776	  }
1777	
1778	  if (selected.length === 0) {
1779	    // 没有可兑现项也成功：明确说明，不保存、不改变记录或计数
1780	    console.log(
1781	      `候补处理完成：本轮处理 ${waiting.length} 项等待候补，没有可兑现项（开放不足或仍有冲突），` +
1782	        '全部继续等待；记录、占用与标识计数不变。',
1783	    );
1784	    for (const {w, gaps, conflicts} of blocked) {
1785	      console.log(renderBlocked(store, w, gaps, conflicts));
1786	    }
1787	    return;
1788	  }
1789	
1790	  // 为每个选中项各生成一项普通预约（不加入系列、不改动原预约），
1791	  // 新预约、候补已兑现状态及关联预约标识一次性原子落盘后才报告成功。
1792	  for (const s of selected) {
1793	    store.bookings.push({
1794	      id: s.bookingId,
1795	      resourceIds: s.w.resourceIds,
1796	      start: s.w.start,
1797	      end: s.w.end,
1798	      status: 'active',
1799	    });
1800	    s.w.status = 'fulfilled';
1801	    s.w.bookingId = s.bookingId;
1802	  }
1803	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
1804	  await saveStore(file, store);
1805	
1806	  const selectedById = new Map(selected.map((s) => [s.w.id, s]));
1807	  const blockedById = new Map(blocked.map((b) => [b.w.id, b]));
1808	  console.log(
1809	    `候补处理完成：按登记顺序处理 ${waiting.length} 项等待候补，本轮兑现 ${selected.length} 项，` +
1810	      `${blocked.length} 项继续等待（已兑现/已取消项未参与）。`,
1811	  );
1812	  for (const w of waiting) { // 结果严格按队列顺序展示
1813	    const s = selectedById.get(w.id);
1814	    if (s) {
1815	      console.log(`- 兑现 ${w.id} → 新预约 ${s.bookingId}（普通预约，不属于任何系列）`);
1816	      console.log(`    时间: ${w.start} → ${w.end}`);
1817	      console.log(`    资源: ${formatResourceIds(store, w.resourceIds)}`);
1818	    } else {
1819	      const b = blockedById.get(w.id)!;
1820	      console.log(renderBlocked(store, w, b.gaps, b.conflicts));
1821	    }
1822	  }
1823	}
1824	
1825	function renderBlocked(
1826	  store: Store,
1827	  w: WaitlistRec,
1828	  gaps: CoverageGap[],
1829	  conflicts: PendingConflict[],
1830	): string {
1831	  const lines = [`- 继续等待 ${w.id}：${w.start} → ${w.end}`];
1832	  if (gaps.length > 0) {
